using System;using System.IO;
class DiscoveryTests{[STAThread]static int Main(string[] args){string root=args[0];Directory.CreateDirectory(root);string discord=Path.Combine(root,"Discord");foreach(string version in new[]{"1.0.9","1.0.10","1.0.11"}){string dir=Path.Combine(discord,"app-"+version);Directory.CreateDirectory(dir);if(version!="1.0.11")File.WriteAllText(Path.Combine(dir,"Discord.exe"),"");}if(!AppDiscovery.DiscordAt(discord)[0].Contains("app-1.0.10"))throw new Exception("Numeric latest installed executable");if(AppDiscovery.DiscordAt(Path.Combine(root,"missing")).Length!=0)throw new Exception("Absent install");string pka=Path.Combine(root,"Pka");Directory.CreateDirectory(pka);foreach(string name in new[]{"PokeAlliance_Launcher.exe","PokeAlliance_dx.exe","PokeAlliance_gl.exe","uninstall.exe"})File.WriteAllText(Path.Combine(pka,name),"");if(AppDiscovery.PkaAt(pka).Length!=3)throw new Exception("Launcher and both clients without uninstaller");foreach(string path in AppDiscovery.Find(false))Console.WriteLine("Detected: "+Path.GetFileName(path));Console.WriteLine("PASS: numeric Discord versions, missing executable/install, PKA clients and exclusion of uninstaller");return 0;}}
